{
  "case_id": "xsu_sg_010_congenital_impairment_documentation",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret dækker i hovedsagen vejledningen, men har en materiel fejl: Det anfører, at ansøgeren \"skal\" vedlægge lægefaglige oplysninger, og at dokumentationen skal vise varige funktionsnedsættelser og indeholde en beskrivelse. Det følger af § 37, stk. 1, så det er korrekt. Problemet er \"Kort praktisk svar\", som anbefaler \"lægefaglig beskrivelse af diagnosen og varigheden\" og \"beskrivelse af aktuelle symptomer og funktionsniveau\". Det kan læses som krav om nyere dokumentation om funktionsniveau, selv om vejledningen netop siger, at den medfødte gruppe ofte ikke har det. Svaret tilføjer også, at ansøgningen kan afvises uden realitetsbehandling, hvis dokumentationen er for sparsom. Det har ingen støtte i kilderne; § 37, stk. 5 giver kun mulighed for en frist for yderligere dokumentation. Svaret nævner heller ikke, at de seneste oplysninger kan være ældre."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle fire kritiske elementer er med. Det gælder sygehistorik og seneste journalnotater, udrednings- og behandlingsforløb samt aktuelle symptomer, epikriser og journalnotater med støtteforanstaltninger som supplement, og en personlig redegørelse hvor lægefaglig dokumentation ikke findes eller som supplement."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer direkte, hvilken dokumentation en ansøger med medfødt funktionsnedsættelse kan sende med, og det indeholder både en liste og et kort praktisk svar."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til identificerbare kilder: SU-bekendtgørelsen (bek. nr. 841 af 2026) og vejledning nr. 10157 af 5. oktober 2026. Påstandene er knyttet til dem via noteknumre."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "De angivne kilder er SU-bekendtgørelsen 2026 nr. 841 og vejledning VEJ nr. 10157 af 05/10/2026. Begge findes i det frosne materiale og er aktuelle og autoritative for opgaven."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Påstanden om, at ansøgningen kan afvises uden realitetsbehandling ved sparsom dokumentation, er knyttet til en kilde (note 7), men ingen frosset passage understøtter den. § 37, stk. 5 handler kun om en frist for yderligere dokumentation. Det \"korte praktiske svar\" med lægefaglig beskrivelse af diagnosen og varigheden samt funktionsniveau er heller ikke dækket af afsnit 4.3 i sin fulde betydning."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en retsvirkning uden støtte i det udleverede materiale: afvisning uden realitetsbehandling ved for sparsom dokumentation. Kilderne nævner i stedet muligheden for at fastsætte en frist, jf. § 37, stk. 5."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret fremhæver, at der ofte ikke findes nyere dokumentation, og at personlig redegørelse kan supplere. Det siger imidlertid ikke udtrykkeligt, at eksemplerne ikke er kumulative krav, og at de seneste oplysninger kan være ældre. Det nævner heller ikke, at redegørelsen ikke ophæver det lægefaglige minimum. Redegørelsen præsenteres som relevant, hvis der ikke findes tilstrækkelig lægefaglig dokumentation, hvilket kan læses som en erstatning af minimumet."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Det er sammenhængende, at svaret først angiver minimumskravet, derefter eksemplerne, så aktualitet og afgrænsning, og til sidst en praktisk opsummering. Konklusionen følger af de trin, der er angivet."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret bruger \"skal\" korrekt om minimumskravene i § 37. Men \"kan ansøgningen blive afvist uden realitetsbehandling\" er en usikker og ikke kildebaseret formulering, og udtrykket \"hvis der ikke findes tilstrækkelig lægefaglig dokumentation\" om personlig redegørelse udvisker forholdet mellem minimum og supplement."
    }
  },
  "xhaile_coverage": {
    "A49": {
      "label": "yes",
      "reason": "Svaret behandler medfødt funktionsnedsættelse. Det nævner, at der ofte ikke findes nyere dokumentation, at sygehistorik og seneste journalnotater er vigtige, og at en personlig redegørelse kan beskrive situationen. Det gengiver ikke eksemplerne på diagnoser eller at listen ikke er udtømmende, men det er ikke afgørende for dokumentationsspørgsmålet."
    },
    "A35": {
      "label": "partial",
      "reason": "Svaret dækker de alternative og supplerende dokumentationsformer: epikriser, journalnotater, støtteafgørelser og skånehensyn samt personlig redegørelse. Det udtrykker dog ikke tydeligt, at redegørelsen ikke erstatter lægefagligt minimum, at eksemplerne ikke er kumulative krav, og det tilføjer en ustøttet afvisningsregel."
    }
  },
  "overall_notes": "Svaret er indholdsmæssigt tæt på vejledningen og dækker alle kritiske elementer. Det har gode kildehenvisninger, men indeholder en ustøttet retsvirkning (afvisning uden realitetsbehandling) og mangler vigtige forbehold om, at ældre oplysninger kan være tilstrækkelige, at eksemplerne ikke er kumulative, og at personlig redegørelse ikke ophæver det lægefaglige minimum."
}

